-- Disposable-only P0 security regression. Synthetic records; rolled back in full.
begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(66);
insert into public.sops(id,title,department_id) values ('91000000-0000-0000-0000-000000000001','P0 Scoped SOP','a0000000-0000-0000-0000-000000000001'),('91000000-0000-0000-0000-000000000002','P0 Unscoped SOP',null),('91000000-0000-0000-0000-000000000003','P0 Foreign SOP','a1000000-0000-0000-0000-000000000001');
insert into public.content_tasks(id,title,pic_name,department_id,user_id) values('92000000-0000-0000-0000-000000000001','P0 Scoped Task','TEST Staff','a0000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000003'),('92000000-0000-0000-0000-000000000002','P0 Unscoped Task','TEST Staff',null,'71000000-0000-0000-0000-000000000003');
insert into public.content_items(id,title,business_unit_id,department_id,user_id) values('93000000-0000-0000-0000-000000000001','P0 Workflow','00000000-0000-0000-0002-000000000001','a0000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000003');
reset role; set local role authenticated; select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000006','authenticated');
select extensions.ok((select count(*)=0 from public.organisations),'INACTIVE: organisations hidden');
select extensions.ok((select count(*)=0 from public.business_units),'INACTIVE: business_units hidden');
select extensions.ok((select count(*)=0 from public.departments),'INACTIVE: departments hidden');
select extensions.ok((select count(*)=0 from public.teams),'INACTIVE: teams hidden');
select extensions.ok((select count(*)=0 from public.profiles),'INACTIVE: profiles hidden');
select extensions.ok((select count(*)=0 from public.user_role_assignment),'INACTIVE: user_role_assignment hidden');
select extensions.ok((select count(*)=0 from public.user_business_unit_access),'INACTIVE: user_business_unit_access hidden');
select extensions.ok((select count(*)=0 from public.user_department_access),'INACTIVE: user_department_access hidden');
select extensions.ok((select count(*)=0 from public.sops),'INACTIVE: sops hidden');
select extensions.ok((select count(*)=0 from public.content_tasks),'INACTIVE: content_tasks hidden');
select extensions.ok((select count(*)=0 from public.work_files),'INACTIVE: work_files hidden');
select extensions.ok((select count(*)=0 from public.activities),'INACTIVE: activities hidden');
select extensions.ok((select count(*)=0 from public.content_ideas),'INACTIVE: content_ideas hidden');
select extensions.ok((select count(*)=0 from public.knowledge_items),'INACTIVE: knowledge_items hidden');
select extensions.ok((select count(*)=0 from public.campaigns),'INACTIVE: campaigns hidden');
select extensions.ok((select count(*)=0 from public.content_items),'INACTIVE: content_items hidden');
select extensions.ok((select count(*)=0 from public.platform_publications),'INACTIVE: platform_publications hidden');
select extensions.ok((select count(*)=0 from public.approval_categories),'INACTIVE: approval_categories hidden');
select extensions.ok((select count(*)=0 from public.approval_action),'INACTIVE: approval_action hidden');
select extensions.ok((select count(*)=0 from public.record_edit_log),'INACTIVE: record_edit_log hidden');
select extensions.ok(not public.ieos_readiness(),'INACTIVE: readiness denied');
select extensions.ok((select count(*)=0 from public.application_access_events),'INACTIVE: access history denied');
select extensions.ok(public.fn_role('71000000-0000-0000-0000-000000000001') is null,'CALLER BINDING: inactive cannot probe Director role');
select extensions.ok(not ieos_stage1_test.probe($q$select public.assign_application_role('71000000-0000-0000-0000-000000000003','management')$q$),'INACTIVE: role assignment denied');
select extensions.ok((select count(*)=0 from public.work_tasks),'INACTIVE: work_tasks hidden');
select extensions.ok((select count(*)=0 from public.work_task_updates),'INACTIVE: work_task_updates hidden');
select extensions.ok((select count(*)=0 from public.daily_work_updates),'INACTIVE: daily_work_updates hidden');
select extensions.ok((select count(*)=0 from public.master_files),'INACTIVE: master_files hidden');
select extensions.ok((select count(*)=0 from public.marketing_leads),'INACTIVE: marketing_leads hidden');
select extensions.ok((select count(*)=0 from public.lead_interactions),'INACTIVE: lead_interactions hidden');
select extensions.ok((select count(*)=0 from public.marketing_lead_events),'INACTIVE: marketing_lead_events hidden');
reset role; set local role authenticated; select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000003','authenticated');
select extensions.ok((select count(*)=0 from public.sops where id='91000000-0000-0000-0000-000000000002'),'DEFAULT DENY: unscoped SOP hidden from staff');
select extensions.ok((select count(*)=0 from public.content_tasks where id='92000000-0000-0000-0000-000000000002'),'DEFAULT DENY: unscoped legacy task hidden from staff');
select extensions.ok((select count(*)=0 from public.knowledge_items),'LEGACY KB: staff denied until explicit classification exists');
select extensions.ok((select count(*)=0 from public.content_ideas),'LEGACY IDEAS: staff denied');
select extensions.ok(not public.fn_has_department_access(auth.uid(),'a1000000-0000-0000-0000-000000000001'),'CROSS COMPANY: absent grant denies access');
select extensions.ok(public.fn_role('71000000-0000-0000-0000-000000000001') is null,'CALLER BINDING: staff cannot probe Director role');
select extensions.ok(not ieos_stage1_test.probe($q$select public.assign_application_role('71000000-0000-0000-0000-000000000003','management')$q$),'ESCALATION: staff cannot assign own role');
select extensions.ok(not ieos_stage1_test.probe($q$insert into public.content_items(title,department_id,user_id,status,approval_status) values('Forged approval','a0000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000003','approved','approved')$q$),'WORKFLOW: pre-approved content insert denied');
select set_config('ieos.workflow_change','on',true);
select extensions.ok(not ieos_stage1_test.probe($q$update public.content_items set status='approved' where id='93000000-0000-0000-0000-000000000001'$q$),'WORKFLOW: session flag cannot forge approval');
select extensions.ok(not ieos_stage1_test.probe($q$insert into public.approval_action(content_item_id,actor_id,action) values('93000000-0000-0000-0000-000000000001','71000000-0000-0000-0000-000000000001','approved')$q$),'AUDIT: approval history cannot be forged');
select extensions.ok((select count(*)=1 from public.sops where id='91000000-0000-0000-0000-000000000001'),'PRESERVATION: scoped SOP remains visible');
select extensions.ok(public.ieos_readiness(),'READINESS: full public candidate is ready for active user');
select extensions.ok(ieos_stage1_test.execute_ok($q$insert into public.activities(task_id,action,actor_name) values('92000000-0000-0000-0000-000000000001','status_changed','Forged Director')$q$),'LEGACY AUDIT: staff can log permitted activity');
select extensions.ok(exists(select 1 from public.activities where task_id='92000000-0000-0000-0000-000000000001' and user_id=auth.uid() and actor_name='TEST Staff'),'LEGACY AUDIT: actor is bound to signed-in staff');
select extensions.ok(not ieos_stage1_test.probe($q$update public.content_tasks set status='approved',approval_status='approved' where id='92000000-0000-0000-0000-000000000001'$q$),'LEGACY REVIEW: staff cannot approve task');
select extensions.ok(not ieos_stage1_test.probe($q$update public.content_tasks set status='submitted' where id='92000000-0000-0000-0000-000000000001'$q$),'LEGACY EVIDENCE: submission without output rejected');
select extensions.ok(not ieos_stage1_test.probe($q$update public.content_tasks set status='posted' where id='92000000-0000-0000-0000-000000000001'$q$),'LEGACY PUBLICATION: cannot post before approval');
select extensions.ok(ieos_stage1_test.execute_ok($q$update public.content_tasks set work_link='https://example.test/output',status='submitted',approval_status='pending' where id='92000000-0000-0000-0000-000000000001'$q$),'LEGACY EVIDENCE: staff submits with output');
reset role; set local role authenticated; select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000002','authenticated');
select extensions.ok((select count(*)=0 from public.content_items where id='88888888-0000-0000-0000-000000000005'),'CROSS COMPANY: null-department content still obeys business-unit access');
select extensions.ok(not public.fn_can_edit_content_item(auth.uid(),'88888888-0000-0000-0000-000000000005'),'CROSS COMPANY: workflow RPC cannot edit foreign unscoped content');
select extensions.ok((select count(*)=0 from public.knowledge_items),'DEFAULT DENY: unclassified legacy knowledge restricted to Director');
select extensions.ok((select count(*)=0 from public.sops where id='91000000-0000-0000-0000-000000000002'),'DEFAULT DENY: manager cannot read unscoped SOP');
select extensions.ok((select count(*)=0 from public.content_tasks where id='92000000-0000-0000-0000-000000000002'),'DEFAULT DENY: manager cannot read unscoped legacy task');
select extensions.ok(ieos_stage1_test.execute_ok($q$update public.content_tasks set status='approved',approval_status='approved' where id='92000000-0000-0000-0000-000000000001'$q$),'LEGACY REVIEW: scoped manager approves');
select extensions.ok(not ieos_stage1_test.probe($q$insert into public.campaigns(name,business_unit_id,department_id) values('Mismatched scope','00000000-0000-0000-0002-000000000001','a1000000-0000-0000-0000-000000000001')$q$),'CAMPAIGN INTEGRITY: mismatched business unit rejected');
select extensions.ok(ieos_stage1_test.affected_rows($q$update public.campaigns set name='Forged foreign campaign' where department_id='a1000000-0000-0000-0000-000000000001'$q$)=0,'CROSS COMPANY: manager cannot edit foreign campaign');
select extensions.ok(not ieos_stage1_test.probe($q$insert into public.campaigns(name,business_unit_id,department_id) values('Foreign write','00000000-0000-0000-0002-000000000002','a1000000-0000-0000-0000-000000000001')$q$),'CROSS COMPANY: manager cannot create foreign campaign');
reset role; set local role authenticated; select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000001','authenticated');
select extensions.ok((select count(*)=1 from public.knowledge_items where id='f0000000-0000-0000-0000-000000000001'),'PRESERVATION: Director retains existing legacy knowledge');
select extensions.ok(ieos_stage1_test.execute_ok($q$select public.assign_application_role('71000000-0000-0000-0000-000000000003','intern')$q$),'ROLE MODEL: Director replaces application role atomically');
select extensions.ok((select count(*)=1 and min(role)='intern' from public.user_role_assignment where profile_id='71000000-0000-0000-0000-000000000003'),'ROLE MODEL: replacement retains exactly one role');
select extensions.ok(exists(select 1 from public.application_access_events where subject_id='71000000-0000-0000-0000-000000000003' and actor_id=auth.uid() and metadata->>'previous_role'='staff' and metadata->>'new_role'='intern'),'ACCESS AUDIT: role replacement preserves actor and prior role');
select extensions.ok(not ieos_stage1_test.probe($q$insert into public.user_role_assignment(profile_id,role) values('71000000-0000-0000-0000-000000000003','staff')$q$),'ROLE MODEL: second simultaneous role rejected');
insert into public.user_department_access(profile_id,department_id) values('71000000-0000-0000-0000-000000000003','a1000000-0000-0000-0000-000000000001');
reset role; set local role authenticated; select ieos_stage1_test.claim('71000000-0000-0000-0000-000000000003','authenticated');
select extensions.ok(public.fn_has_department_access(auth.uid(),'a1000000-0000-0000-0000-000000000001'),'EXPLICIT GRANT: cross-company department grant works');
reset role; set local role anon; select ieos_stage1_test.claim(null,'anon');
select extensions.ok(not ieos_stage1_test.probe($q$select * from public.sops$q$),'ANONYMOUS: legacy SOP access denied');
select extensions.ok(not ieos_stage1_test.probe($q$select public.ieos_readiness()$q$),'ANONYMOUS: readiness RPC denied');
reset role; select * from extensions.finish(); rollback;
